queue = [start]; visited = {start}; steps = 0
while queue:
    for _ in range(len(queue)):
        node = queue.popleft()
        if node is goal: return steps
        for nb in neighbours(node):
            if nb not in visited:
                visited.add(nb)
                queue.append(nb)
    steps += 1
return -1

